span.wswidebeam__pi{opacity:1;width:58px;height:58px;border-radius:50%;background:#ffd9b2;border:1px solid #ff8000;color:#b05800;display:flex;align-items:center;justify-content:center;margin:0 auto 14px}.wswidebeam__pi svg{width:28px;height:28px}
.wswidebeam__red3 span.wswidebeam__pi{width:44px;height:44px;margin-bottom:8px}.wswidebeam__red3 .wswidebeam__pi svg{width:22px;height:22px}.wswidebeam__red3>div{border-color:rgba(255,128,0,.35)}
.wswidebeam__pog strong{color:#1c1c1c}.wswidebeam__st,.wswidebeam__kv li::before{background:#b05800}.wswidebeam__tab th{background:#b05800!important}
.wswidebeam__ti{background:linear-gradient(135deg,#b05800,#c17d38);box-shadow:0 6px 14px rgba(176,88,0,.30)}.wswidebeam__tk{border-color:rgba(255,128,0,.30)}
.wswidebeam__ime{display:flex;align-items:center;gap:10px}.wswidebeam__av{flex:0 0 34px;width:34px;height:34px;border-radius:50%;background:#ffd9b2;border:1px solid #ff8000;color:#b05800;font-style:normal;font-weight:800;font-size:14px;display:inline-flex;align-items:center;justify-content:center}
div.wswidebeam__pog{text-align:center;border:1px solid rgba(255,128,0,.35);border-radius:16px;transition:transform .2s,box-shadow .2s}div.wswidebeam__pog:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(255,128,0,.22)}div.wswidebeam__pog>strong,div.wswidebeam__pog>span:not(.wswidebeam__pi){display:block}
.wswidebeam__pus{color:#b05800}.wswidebeam__plavo{background:#b05800;margin-top:-72px}.wswidebeam__k--temna{background:#b05800}
@media (max-width:860px){.wswidebeam__s{padding:46px 0}.wswidebeam__s.wswidebeam__traka{padding:30px 0}.wswidebeam__plavo{margin-top:-46px}.wswidebeam__pog>div{padding:22px 12px}}
@media (max-width:767px){.wswidebeam__v{padding:0 16px}}
